const ROUTES = [
  '(tabs)/index',
  '(tabs)/stats',
  'settings/index',
  'settings/units',
  'hikes/new',
  'hikes/[id]',
  'hikes/[id]/photos',
  'trails/[...path]',
];

function segmentsOf(route) {
  const segs = route.split('/').filter((s) => !/^\(.+\)$/.test(s));
  if (segs[segs.length - 1] === 'index') segs.pop();
  return segs;
}

function tryMatch(route, parts) {
  const pattern = segmentsOf(route);
  const params = {};
  let rank = '';
  for (let i = 0; i < pattern.length; i++) {
    const seg = pattern[i];
    const catchAll = seg.match(/^\[\.\.\.(\w+)\]$/);
    const dynamic = seg.match(/^\[(\w+)\]$/);
    if (catchAll) {
      const rest = parts.slice(i);
      if (rest.length === 0) return null;
      params[catchAll[1]] = rest;
      return { route, params, rank: rank + '1' };
    }
    if (i >= parts.length) return null;
    if (dynamic) {
      params[dynamic[1]] = parts[i];
      rank += '2';
    } else if (seg === parts[i]) {
      rank += '3';
    } else {
      return null;
    }
  }
  return pattern.length === parts.length ? { route, params, rank } : null;
}

function matchRoute(url, routes) {
  const [path, query = ''] = url.split('?');
  const parts = path.split('/').filter(Boolean);
  let best = null;
  for (const route of routes) {
    const m = tryMatch(route, parts);
    if (m && (!best || m.rank > best.rank)) best = m;
  }
  if (!best) return null;
  const params = { ...best.params };
  for (const [key, value] of new URLSearchParams(query)) params[key] = value;
  return { route: best.route, params };
}

console.log(JSON.stringify(matchRoute('/hikes/42?units=mi', ROUTES)));
